// Parses one JSON string literal starting at p into Unicode code points.
static vector<int> jsonString() {
    skipSpace();
    vector<int> s;
    p++;  // opening quote
    auto hex4 = [&]() {
        int v = stoi(in.substr(p, 4), nullptr, 16);
        p += 4;
        return v;
    };
    while (in[p] != '"') {
        unsigned char c = in[p];
        if (c == '\\') {
            char e = in[p + 1];
            p += 2;
            if (e == 'u') {
                int v = hex4();
                if (v >= 0xD800 && v < 0xDC00 && in[p] == '\\' && in[p + 1] == 'u') {
                    p += 2;
                    int lo = hex4();
                    v = 0x10000 + ((v - 0xD800) << 10) + (lo - 0xDC00);
                }
                s.push_back(v);
            } else {
                s.push_back(e == 'n' ? '\n' : e == 't' ? '\t' : e == 'r' ? '\r' : e == 'b' ? '\b' : e == 'f' ? '\f' : e);
            }
        } else {
            // Raw UTF-8 sequence.
            int len = c < 0x80 ? 1 : c < 0xE0 ? 2 : c < 0xF0 ? 3 : 4;
            int v = len == 1 ? c : c & (0x3F >> (len - 1));
            for (int k = 1; k < len; k++) v = (v << 6) | (in[p + k] & 0x3F);
            s.push_back(v);
            p += len;
        }
    }
    p++;  // closing quote
    return s;
}

