public class Main {
    static String text;
    static int at = 0;

    // Parses one JSON string literal starting at `at` into Unicode code points.
    static int[] jsonString() {
        while (Character.isWhitespace(text.charAt(at))) at++;
        at++;  // opening quote
        StringBuilder sb = new StringBuilder();
        while (text.charAt(at) != '"') {
            char c = text.charAt(at++);
            if (c != '\\') {
                sb.append(c);
                continue;
            }
            char e = text.charAt(at++);
            switch (e) {
                case 'n' -> sb.append('\n');
                case 't' -> sb.append('\t');
                case 'r' -> sb.append('\r');
                case 'b' -> sb.append('\b');
                case 'f' -> sb.append('\f');
                case 'u' -> {
                    sb.append((char) Integer.parseInt(text.substring(at, at + 4), 16));
                    at += 4;
                }
                default -> sb.append(e);
            }
        }
        at++;  // closing quote
        // Escaped surrogate pairs merge into one code point here.
        return sb.toString().codePoints().toArray();
    }

    public static void main(String[] args) throws Exception {
        text = new String(System.in.readAllBytes(), java.nio.charset.StandardCharsets.UTF_8);
        int[] a = jsonString(), b = jsonString();
        if (a.length < b.length) {
            int[] t = a;
            a = b;
            b = t;
        }
        // Rolling LCS over the shorter string.
        int[] row = new int[b.length + 1];
        for (int x : a) {
            int diagonal = 0;
            for (int j = 1; j <= b.length; j++) {
                int old = row[j];
                row[j] = x == b[j - 1] ? diagonal + 1 : Math.max(row[j], row[j - 1]);
                diagonal = old;
            }
        }
        System.out.println(a.length + b.length - 2 * row[b.length]);
    }
}

