	json.Unmarshal([]byte(lines[1]), &sb)
	a, b := []rune(sa), []rune(sb) // count Unicode code points
	if len(a) < len(b) {
		a, b = b, a
	}
	// Rolling LCS over the shorter string.
	row := make([]int, len(b)+1)
	for _, x := range a {
